"""Build the Greek usage guide. Edit the page content below the layout helpers."""

from pathlib import Path
from reportlab.pdfgen import canvas
from reportlab.lib import colors
from reportlab.lib.styles import ParagraphStyle
from reportlab.platypus import Paragraph, Table, TableStyle
from reportlab.pdfbase import pdfmetrics
from reportlab.pdfbase.ttfonts import TTFont
from PIL import Image
GUIDE_DIR = Path(__file__).resolve().parent
ROOT = GUIDE_DIR.parent.parent
OUT = GUIDE_DIR / 'faethon-odigos-chrisis.pdf'
SH = GUIDE_DIR / 'screenshots'
for name, file in [('Body', 'Carlito-Regular.ttf'), ('Bold', 'Carlito-Bold.ttf'), ('Italic', 'Carlito-Italic.ttf')]:
    pdfmetrics.registerFont(TTFont(name, str(ROOT / 'src/Api/Fonts' / file)))
pdfmetrics.registerFontFamily('Body', normal='Body', bold='Bold', italic='Italic', boldItalic='Bold')
W, H = (595.276, 841.89)
M = 40
CW = W - 2 * M
RED = colors.HexColor('#53231f')
INK = colors.HexColor('#222222')
MUTED = colors.HexColor('#68635e')
LIGHT = colors.HexColor('#f5f0e8')
c = canvas.Canvas(str(OUT), pagesize=(W, H))
c.setTitle('Faethon Label Studio | Οδηγός χρήσης')
c.setAuthor('Faethon')
c.setSubject('Ετικέτες, παραγωγή, πιστοποιητικά και διαχείριση')
styles = {'body': ParagraphStyle('body', fontName='Body', fontSize=11, leading=14.3, textColor=INK, spaceAfter=6), 'small': ParagraphStyle('small', fontName='Body', fontSize=9.1, leading=11.5, textColor=MUTED), 'h2': ParagraphStyle('h2', fontName='Bold', fontSize=13, leading=16, textColor=INK), 'cell': ParagraphStyle('cell', fontName='Body', fontSize=10.2, leading=13, textColor=INK)}
y = 0
page = 0

def p(text, style='body', gap=6):
    global y
    q = Paragraph(text, styles[style])
    _, h = q.wrap(CW, 700)
    if y - h < 43:
        raise RuntimeError(f'Overflow page {page}: {text[:55]} y={y} h={h}')
    q.drawOn(c, M, y - h)
    y -= h + gap

def head(text):
    p(text, 'h2', 7)

def note(text):
    global y
    q = Paragraph(text, styles['body'])
    _, h = q.wrap(CW - 22, 700)
    c.setFillColor(LIGHT)
    c.roundRect(M, y - h - 19, CW, h + 19, 5, fill=1, stroke=0)
    q.drawOn(c, M + 11, y - h - 9)
    y -= h + 28

def shot(name, caption):
    global y
    path = SH / name
    im = Image.open(path)
    assert im.width * 9 == im.height * 16
    h = CW * 9 / 16
    c.drawImage(str(path), M, y - h, width=CW, height=h)
    c.setStrokeColor(colors.HexColor('#ddd7ce'))
    c.rect(M, y - h, CW, h, stroke=1, fill=0)
    y -= h + 6
    p(caption, 'small', 12)

def table(headers, rows, widths):
    global y
    content = [[Paragraph('<b>' + s + '</b>', styles['cell']) for s in headers]] + [[Paragraph(s, styles['cell']) for s in row] for row in rows]
    t = Table(content, colWidths=[CW * w for w in widths])
    t.setStyle(TableStyle([('BACKGROUND', (0, 0), (-1, 0), LIGHT), ('GRID', (0, 0), (-1, -1), 0.4, colors.HexColor('#d9d9d9')), ('VALIGN', (0, 0), (-1, -1), 'TOP'), ('LEFTPADDING', (0, 0), (-1, -1), 9), ('RIGHTPADDING', (0, 0), (-1, -1), 9), ('TOPPADDING', (0, 0), (-1, -1), 7), ('BOTTOMPADDING', (0, 0), (-1, -1), 7)]))
    _, h = t.wrap(CW, 700)
    if y - h < 43:
        raise RuntimeError(f'Table overflow {page} {y - h}')
    t.drawOn(c, M, y - h)
    y -= h + 12

def new(title, sub):
    global page, y
    if page:
        c.showPage()
    page += 1
    c.bookmarkPage(f'p{page}')
    c.addOutlineEntry(title, f'p{page}', 0, False)
    c.setFillColor(RED)
    c.setFont('Bold', 9)
    c.drawString(M, H - 31, 'FAETHON  /  LABEL STUDIO')
    c.setFillColor(MUTED)
    c.setFont('Body', 8)
    c.drawRightString(W - M, H - 31, 'ΟΔΗΓΟΣ ΧΡΗΣΗΣ  •  24.09.2026')
    c.setFillColor(INK)
    c.setFont('Bold', 23)
    c.drawString(M, H - 69, title)
    y = H - 90
    p(sub, 'small', 14)
    c.setFont('Body', 8)
    c.setFillColor(MUTED)
    c.drawString(M, 24, 'Faethon Labeller  •  Ελληνικός οδηγός')
    c.drawRightString(W - M, 24, f'{page:02d} / 12')
new('Οδηγός χρήσης', 'Faethon Label Studio  /  Ετικέτες, παραγωγή, πιστοποιητικά και διαχείριση')
p('Ο οδηγός καλύπτει τη χρήση του Label Studio από χειριστές και διαχειριστές. Η καθημερινή διαδρομή είναι: <b>επιλογή προϊόντος → στοιχεία παραγωγής → προεπισκόπηση → εκτύπωση → έλεγχος ιστορικού</b>.')
shot('01-dashboard.png', 'Εικόνα 1  Η Επισκόπηση συγκεντρώνει τις συντομεύσεις και τις πρόσφατες εκτυπώσεις.')
head('Σύνδεση και πλοήγηση')
p('Ανοίξτε τη διεύθυνση που σας έχει δώσει ο διαχειριστής, εισαγάγετε όνομα χρήστη και κωδικό και πατήστε <b>Είσοδος</b>. Ελέγξτε την ένδειξη <b>Συνδεδεμένο</b>. Το αριστερό μενού αλλάζει ενότητα· η <b>Αποσύνδεση</b> βρίσκεται κάτω αριστερά.')
p('Ο <b>χειριστής</b> εκδίδει ετικέτες και πιστοποιητικά, διαχειρίζεται πελάτες και καθημερινή λίστα. Ο <b>διαχειριστής</b> επεξεργάζεται επιπλέον τα βασικά δεδομένα, κάνει εισαγωγές και ρυθμίζει χρήστες και εκτυπωτές.')
head('Βρείτε γρήγορα την εργασία σας')
for text in ['<link href="#p2">Ετικέτες και μορφές  02–03</link>  ·  <link href="#p4">Καθημερινή παραγωγή  04</link>  ·  <link href="#p5">Ιστορικό  05</link>', '<link href="#p6">Προϊόντα  06</link>  ·  <link href="#p7">Συστάσεις  07</link>  ·  <link href="#p8">Κοινά κείμενα και πελάτες  08</link>', '<link href="#p9">Πιστοποιητικά  09</link>  ·  <link href="#p10">Εισαγωγές Excel  10</link>  ·  <link href="#p11">Ρυθμίσεις  11–12</link>']:
    p(text, 'body', 3)
p('Τα στιγμιότυπα προέρχονται από την εφαρμογή της 24.09.2026 και έχουν αναλογία 16:9. Οι τιμές που εμφανίζονται είναι παραδείγματα χρήσης.', 'small')
new('Επιλογή και προετοιμασία ετικέτας', 'Έκδοση ετικετών  /  Από το προϊόν στα στοιχεία της παρτίδας')
shot('02-search.png', 'Εικόνα 2  Αναζήτηση με περιγραφή και φίλτρα πριν από την επιλογή προϊόντος.')
p('<b>1.</b> Ανοίξτε <b>Έκδοση ετικετών</b> ή <b>Νέα εκτύπωση</b>. Αναζητήστε περιγραφή ή κωδικό. Περιορίστε τη λίστα σε ενεργά, καθημερινά, private label ή είδη κρεοπωλείου και χρησιμοποιήστε τα φίλτρα οικογένειας, τμήματος, κατάστασης και συσκευασίας.')
p('<b>2.</b> Στη σωστή γραμμή πατήστε <b>Έκδοση ετικέτας</b>. Επιβεβαιώστε κωδικό, περιγραφή και νωπό/κατεψυγμένο. Επιλέξτε επωνυμία, μορφή και διαθέσιμη γλώσσα. Οι επιλογές εξαρτώνται από το προϊόν και την επωνυμία.')
p('<b>3.</b> Συμπληρώστε ημερομηνία παραγωγής, ημέρες λήξης και βάρος. Για κατεψυγμένο είδος ελέγξτε την ημερομηνία κατάψυξης. Για κιβώτιο ή παλέτα συμπληρώστε τα αντίστοιχα βάρη και τεμάχια που εμφανίζονται.')
p('<b>4.</b> Ανοίξτε <b>Ιχνηλασιμότητα και πρόσθετα στοιχεία</b> για προμηθευτή, συσκευασία, σχόλιο και ειδικά πεδία. Όταν ζητούνται, συμπληρώστε κωδικό ζώου και αριθμό έγκρισης σφαγείου.')
head('LOT και ημερομηνία λήξης')
p('Το LOT υπολογίζεται από τα στοιχεία του προϊόντος, την οικογένεια της σύστασης και την παραγωγή. Η λήξη υπολογίζεται ως ημερομηνία παραγωγής συν ημέρες λήξης. Η <b>Χειροκίνητη ημερομηνία λήξης</b> υπερισχύει αυτού του υπολογισμού. Τα βάρη καταχωρούνται σε kg.')
note('<b>Αποθήκευση προετοιμασίας:</b> πατήστε Αποθήκευση και ανακαλέστε την από την Αποθηκευμένη προετοιμασία. Πριν τη χρησιμοποιήσετε ξανά, ελέγξτε ημερομηνίες και βάρη. Η αποθήκευση δεν στέλνει εκτύπωση.')
new('Προεπισκόπηση και μορφές', 'Έκδοση ετικετών  /  Έλεγχος πριν από την αποστολή')
shot('03-label.png', 'Εικόνα 3  Πραγματική προεπισκόπηση μεγάλης ετικέτας με το επιλεγμένο προϊόν.')
p('Πατήστε <b>Προεπισκόπηση</b> και ελέγξτε περιγραφή, επωνυμία, γλώσσα, συστατικά, αλλεργιογόνα, βάρος, LOT και ημερομηνίες. Με <b>Άνοιγμα PDF</b> βλέπετε ολόκληρο το έγγραφο. Διορθώστε όλα τα μηνύματα «Πριν από την εκτύπωση». Μετά από αλλαγή στοιχείων δημιουργήστε νέα προεπισκόπηση.')
p('Επιλέξτε επικυρωμένο, συμβατό <b>Εκτυπωτή</b>, ορίστε <b>Αριθμό αντιτύπων</b> (1–10.000) και πατήστε <b>Αποστολή για εκτύπωση</b>. Παρακολουθήστε την εργασία στο Ιστορικό. Για πολυσέλιδο έγγραφο ανοίξτε το PDF και εκτυπώστε όλες τις σελίδες από εκεί.')
table(['Μορφή ή διαδρομή', 'Τι συμπληρώνετε'], [['Μεγάλη / Κιβώτιο / Μικρή / Παλέτα Α4', 'Στοιχεία παραγωγής και το αντίστοιχο βάρος. Η μικρή έχει μία γλώσσα· η πηγή βάρους ορίζεται στο προϊόν.'], ['Επισκόπηση → Δείγμα', 'Προϊόν ή μορφή με στοιχεία πελάτη. Χωρίς πελάτη, το σχετικό πλαίσιο μένει κενό.'], ['Ελεύθερη ετικέτα / Προς παραγωγή', 'Κείμενο ή περιγραφή. Στο «Προς παραγωγή» ημερομηνία και σχετικό πεδίο μένουν κενά για χειρόγραφη συμπλήρωση.'], ['Κρεοπωλείο / Πελάτες', 'Κρεοπωλείο: επιλέξτε σχετικό είδος. Πελάτες: το εικονίδιο εκτυπωτή ανοίγει ετικέτα διεύθυνσης.']], [0.36, 0.64])
new('Καθημερινή παραγωγή', 'Πολλά προϊόντα σε μία ελεγχόμενη παρτίδα')
shot('04-daily.png', 'Εικόνα 4  Σειρά προϊόντων, βάρος και αριθμός αντιτύπων ανά είδος.')
p('<b>1.</b> Προσθέστε τα είδη από την έκδοση ετικέτας: ανοίξτε <b>Καθημερινή λίστα &amp; συνδεδεμένες επωνυμίες</b> και ενεργοποιήστε <b>Καθημερινό</b>. Η επιλογή αποθηκεύεται αμέσως στο προϊόν. Στη λίστα εμφανίζονται ενεργά καθημερινά είδη, εκτός κρεοπωλείου.')
p('<b>2.</b> Στην <b>Καθημερινή παραγωγή</b> ελέγξτε την ημερομηνία: αρχικά προτείνεται η <b>επόμενη ημέρα</b>. Επιλέξτε τον σωστό εκτυπωτή μεγάλων ετικετών.')
p('<b>3.</b> Συμπληρώστε βάρος και αντίτυπα ανά είδος. <b>Μηδέν αντίτυπα σημαίνει ότι το είδος παραλείπεται.</b> Με τα βέλη αλλάξτε σειρά και πατήστε <b>Αποθήκευση σειράς</b> αν θέλετε να διατηρηθεί.')
p('<b>4.</b> Πατήστε <b>Έλεγχος παρτίδας</b>. Ανοίξτε τα PDF από τους συνδέσμους που εμφανίζονται και διορθώστε τις παρατηρήσεις. Αλλαγή σε ημερομηνία, σειρά, βάρος ή ποσότητα απαιτεί νέο έλεγχο.')
p('<b>5.</b> Πατήστε <b>Εκτύπωση παρτίδας</b> και ελέγξτε τις εργασίες στο Ιστορικό. Αν η υποβολή διακοπεί, οι ήδη υποβλημένες γραμμές σημειώνονται «Στην ουρά». Ελέγξτε τις πριν συνεχίσετε ή ξεκινήσετε νέα παρτίδα.')
note('<b>Διαφορά αποθήκευσης:</b> η Αποθήκευση σειράς κρατά τη διάταξη της λίστας. Τα βάρη και τα αντίτυπα της τρέχουσας οθόνης χρειάζονται έλεγχο σε κάθε νέα παρτίδα.')
new('Ιστορικό και επανεκτύπωση', 'Ιστορικό εκτυπώσεων  /  Τι έγινε με την εργασία')
p('Αναζητήστε <b>LOT, προϊόν ή χειριστή</b> και πατήστε <b>Ανανέωση</b> για την τρέχουσα κατάσταση. Κάθε γραμμή δείχνει ημερομηνία, αντίτυπα και τυχόν λεπτομέρειες. Ο σύνδεσμος <b>PDF</b> ανοίγει το αποθηκευμένο έγγραφο της εργασίας.')
table(['Κατάσταση', 'Ενέργεια χειριστή'], [['Στην ουρά', 'Αναμένει τον βοηθό εκτύπωσης. Η «Επίλυση» ακυρώνει την εργασία με καταχώρηση αιτίας.'], ['Υποβολή', 'Ο βοηθός χειρίζεται την εργασία. Περιμένετε και ανανεώστε· δεν προσφέρεται επανεκτύπωση.'], ['Στάλθηκε στην ουρά Windows', 'Έγινε υποβολή στην ουρά. Ελέγξτε ότι βγήκαν τα σωστά φυσικά αντίτυπα.'], ['Απαιτείται έλεγχος / Αποτυχία', 'Ελέγξτε εκτυπωτή και ουρά Windows. Πατήστε «Επίλυση» και καταγράψτε το αποτέλεσμα. Η κατάσταση γίνεται «Ελέγχθηκε».'], ['Ελέγχθηκε / Ακυρώθηκε', 'Έχει καταγραφεί η επίλυση ή η ακύρωση. Χρησιμοποιήστε «Επανεκτύπωση» μόνο αν χρειάζονται νέα αντίτυπα.']], [0.34, 0.66])
head('Πότε χρησιμοποιείτε την Επανεκτύπωση')
p('Πατήστε <b>Επανεκτύπωση</b> στην επιθυμητή εργασία και πληκτρολογήστε τον αριθμό αντιτύπων. Αναπαράγεται το αποθηκευμένο περιεχόμενο της παλιάς εργασίας. Αν θέλετε διαφορετική ημερομηνία, βάρος ή διορθωμένο κείμενο, επιστρέψτε στην <b>Έκδοση ετικετών</b> και δημιουργήστε νέα προεπισκόπηση.')
